//object that represents a class
class ClassInfo{
   String name;
   String parent;
   HashMap<String, String>fields;
   HashMap<String,MethodInfo>methods;
   ClassInfo(String name, String parent){
      this.name=name;
      this.parent=parent;
      this.fields=new HashMap<>();
      this.methods=new HashMap<>();
   }
}
class MethodInfo{
   String name;
   String returnType;
   HashMap<String, String>params;
   HashMap<String, String>locals;
   ArrayList<String>paramTypes;
   MethodInfo(String name, String returnType){
      this.name=name;
      this.returnType=returnType;
      this.params=new HashMap<>();
      this.locals=new HashMap<>();
      this.paramTypes=new ArrayList<>();
   }
}

