   String lookupFieldType(String className, String fieldName){
      HashSet<String>seen=new HashSet<>();
      while(className!=null){
         if(seen.contains(className)){
            return null;
         }
         seen.add(className);
         ClassInfo c=classes.get(className);
         if(c==null){
            return null;
         }
         if(c.fields.containsKey(fieldName)){
            return c.fields.get(fieldName);
         }
         className=c.parent;
      }
      return null;
   }
   String lookupVarType(String name){
      if(currentClass==null){
         return null;
      }
      if(insideMethod && currentMethod!=null){
         ClassInfo c=classes.get(currentClass);
         if(c!=null){
            MethodInfo m=c.methods.get(currentMethod);
            if(m!=null){
               //local variable
               if(m.locals.containsKey(name)){
                  return m.locals.get(name);
               }
               //parameter
               if(m.params.containsKey(name)){
                  return m.params.get(name);
               }
            }
         }
      }
      return lookupFieldType(currentClass, name);
   }
   MethodInfo lookupMethod(String className, String methodName){
      HashSet<String> seen= new HashSet<>();
      while(className!=null){
         if(seen.contains(className)){
            return null;
         }
         seen.add(className);
         ClassInfo c=classes.get(className);
         if(c==null){
            return null;
         }
         if(c.methods.containsKey(methodName)){
            return c.methods.get(methodName);
         }
         className=c.parent;
      }
      return null;
   }
   boolean isSubtype(String child, String parent){
      if(child==null || parent==null){
         return false;
      }
      if(child.equals(parent)){
         return true;
      }
      String current=child;
      HashSet<String>seen=new HashSet<>();
      while(current!=null){
         if(seen.contains(current)){
            return false;
         }
         seen.add(current);
         ClassInfo c=classes.get(current);
         if(c==null){
            return false;
         }
         current=c.parent;
         if(parent.equals(current)){
            return true;
         }
      }
      return false;
   }
   MethodInfo lookupParentMethod(String className, String methodName){
      ClassInfo c=classes.get(className);
      if(c==null){
         return null;
      }
      String parent=c.parent;
      HashSet<String> seen=new HashSet<>();
      while(parent!=null){
         if(seen.contains(parent)){
            return null;
         }
         seen.add(parent);
         ClassInfo p=classes.get(parent);
         if(p==null){
            return null;
         }
         if(p.methods.containsKey(methodName)){
            return p.methods.get(methodName);
         }
         parent=p.parent;
      }
      return null;
   }
   boolean hasCycle(String className){
      HashSet<String>seen=new HashSet<>();
      String current=className;
      while(current!=null){
         if(seen.contains(current)){
            return true;
         }
         seen.add(current);
         ClassInfo c=classes.get(current);
         if(c==null){
            return false;
         }
         current=c.parent;
      }
      return false;
   }
   boolean checkOverride(String className, MethodInfo childMethod){
      MethodInfo parentMethod=lookupParentMethod(className, childMethod.name);
      if(parentMethod==null){
         return true;
      }
      if(!isSubtype(childMethod.returnType, parentMethod.returnType)){
         return false;
      }
      if(parentMethod.paramTypes.size()!=childMethod.paramTypes.size()){
         return false;
      }
      for(int i=0;i<childMethod.paramTypes.size();i++){
         if(!parentMethod.paramTypes.get(i).equals(childMethod.paramTypes.get(i))){
            return false;
         }
      }
      return true;
   }

